@router.get("/interviews/evaluations/{evaluation_id}")
async def get_candidate_evaluation(
    evaluation_id: int,
    current_user: User = Depends(get_current_user)
):
    try:
        eval_record = await CandidateEvaluation.objects.select_related(
            ["candidate", "interviewer"]
        ).get(id=evaluation_id)
    except ormar.NoMatch:
        raise HTTPException(status_code=404, detail="Candidate evaluation not found")

    if eval_record.candidate.department_id != current_user.department_id and not current_user.is_recruiting_lead:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to view evaluations for this requisition")
    return eval_record
